/** bool8 FldEff_CutGrass(void)
 *  Source : src/fldeff_cut.c */
export function FldEff_CutGrass(rt: DecompRuntime, ...args: any[]): any {
  let x, y;
      let i = 0;

      PlaySE(SE_M_CUT);
      PlayerGetDestCoords(gPlayerFacingPosition.x, gPlayerFacingPosition.y);
      for (i = 0; i < CUT_HYPER_AREA; i++)
      {
          if (sHyperCutTiles[i] == true)
          {
              let xAdd = (i % 5) - 2;
              let yAdd = (i / 5) - 2;

              x = xAdd + gPlayerFacingPosition.x;
              y = yAdd + gPlayerFacingPosition.y;

              SetCutGrassMetatile(x, y);
              AllowObjectAtPosTriggerGroundEffects(x, y);
          }
      }

      SetCutGrassMetatiles(gPlayerFacingPosition.x - sTileCountFromPlayer_X, gPlayerFacingPosition.y - (1 + sTileCountFromPlayer_Y));
      DrawWholeMapView();
      sCutGrassSpriteArrayPtr = AllocZeroed(CUT_SPRITE_ARRAY_COUNT);

       
      for (i = 0; i < CUT_SPRITE_ARRAY_COUNT; i++)
      {
          sCutGrassSpriteArrayPtr[i] = rt.CreateSpriteFromTemplate('sSpriteTemplate_CutGrass', 
          rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x + 8, rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y + 20, 0);
          _gs(rt, sCutGrassSpriteArrayPtr[i]).data[2] = 32 * i;
      }

      return false;
}

