/** bool8 FldEff_SecretPowerTree(void)
 *  Source : src/fldeff_misc.c */
export function FldEff_SecretPowerTree(rt: DecompRuntime, ...args: any[]): any {
  let mb = MapGridGetMetatileBehaviorAt(gPlayerFacingPosition.x, gPlayerFacingPosition.y) & 0xFFF;

      if (mb == MB_SECRET_BASE_SPOT_TREE_LEFT)
          gFieldEffectArguments[7] = 0;

      if (mb == MB_SECRET_BASE_SPOT_TREE_RIGHT)
          gFieldEffectArguments[7] = 2;

      AdjustSecretPowerSpritePixelOffsets();

      rt.CreateSpriteFromTemplate('sSpriteTemplate_SecretPowerTree', 
                   rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x + gFieldEffectArguments[5],
                   rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y + gFieldEffectArguments[6],
                   148);

      if (gFieldEffectArguments[7] == 1 || gFieldEffectArguments[7] == 3)
          ToggleSecretBaseEntranceMetatile();

      return false;
}

