/** bool8 FldEff_SandPillar(void)
 *  Source : src/fldeff_misc.c */
export function FldEff_SandPillar(rt: DecompRuntime, ...args: any[]): any {
  let x, y;

      LockPlayerFieldControls();
      GetXYCoordsOneStepInFrontOfPlayer(x, y);

      gFieldEffectArguments[5] = x;
      gFieldEffectArguments[6] = y;

      switch (GetPlayerFacingDirection())
      {
      case DIR_SOUTH:
          rt.CreateSpriteFromTemplate('sSpriteTemplate_SandPillar', 
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x + 8,
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y + 32,
                       0);

          break;

      case DIR_NORTH:
          rt.CreateSpriteFromTemplate('sSpriteTemplate_SandPillar', 
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x + 8,
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y,
                       148);

          break;

      case DIR_WEST:
          rt.CreateSpriteFromTemplate('sSpriteTemplate_SandPillar', 
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x - 8,
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y + 16,
                       148);

          break;

      case DIR_EAST:
          rt.CreateSpriteFromTemplate('sSpriteTemplate_SandPillar', 
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].x + 24,
                       rt.gba.oam[_gs(rt, gPlayerAvatar.spriteId).oamIndex].y + 16,
                       148);

          break;
      }

      return false;
}

